  ('70000001-0000-0000-0000-000000002501','63000005-0000-0000-0000-000000002501','6400002D-0000-0000-0000-000000002501','responded','minor','Inoculum lot vs challenge preparation log','10000000-0000-0000-0000-000000000001',now()),
  ('70000002-0000-0000-0000-000000002501','63000007-0000-0000-0000-000000002501','6400003E-0000-0000-0000-000000002501','open','major','Mortality of 4 birds with bloody droppings (fecal score 3) at D6 post-challenge exceeds the daily threshold — investigate for severe cecal coccidiosis and notify the study veterinarian.','10000000-0000-0000-0000-000000000001',now()),
  ('70000001-0000-0000-0000-000000002502','63000003-0000-0000-0000-000000002502','64000018-0000-0000-0000-000000002502','open','major','Rectal temperature 40.6 °C exceeds the bovine range (38.0–39.3 °C) — consistent with a febrile BRD episode; confirm against source and the screening reading. (Heart rate 120 bpm is also above the adult range 48–84 bpm for this 14-month animal.)','10000000-0000-0000-0000-000000000001',now()),
  ('70000002-0000-0000-0000-000000002502','63000009-0000-0000-0000-000000002502','64000053-0000-0000-0000-000000002502','responded','minor','Dosing weight vs arrival weight','10000000-0000-0000-0000-000000000001',now()),
  ('70000001-0000-0000-0000-000000000801','63000009-0000-0000-0000-000000000801','64000037-0000-0000-0000-000000000801','open','minor','Baseline PVAS vs owner diary','10000000-0000-0000-0000-000000000001',now()),
  ('70000002-0000-0000-0000-000000000801','6300000F-0000-0000-0000-000000000801','64000061-0000-0000-0000-000000000801','responded','minor','Screening weight vs referral record','10000000-0000-0000-0000-000000000001',now()),
