insert into query_messages (id, query_id, author_id, body) values
  ('71000001-0000-0000-0000-000000002501','70000001-0000-0000-0000-000000002501','10000000-0000-0000-0000-000000000001','Inoculum lot INO-3391 is not recorded on the challenge preparation log for this date. Confirm the lot and that the oocyst suspension was within its potency window.'),
  ('71000002-0000-0000-0000-000000002501','70000001-0000-0000-0000-000000002501','10000000-0000-0000-0000-000000000001','Reconciled — INO-3391 was prepared the same morning; the prep log entry was filed under the prior page. Lot and titre confirmed.'),
  ('71000003-0000-0000-0000-000000002501','70000002-0000-0000-0000-000000002501','10000000-0000-0000-0000-000000000001','Auto edit-check: Mortality of 4 birds with bloody droppings (fecal score 3) at D6 post-challenge exceeds the daily threshold — investigate for severe cecal coccidiosis and notify the study veterinarian.'),
  ('71000001-0000-0000-0000-000000002502','70000001-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Auto edit-check: Rectal temperature 40.6 °C exceeds the bovine range (38.0–39.3 °C) — consistent with a febrile BRD episode; confirm against source and the screening reading. (Heart rate 120 bpm is also above the adult range 48–84 bpm for this 14-month animal.)'),
  ('71000002-0000-0000-0000-000000002502','70000002-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Body weight at dosing (278 kg) differs from the arrival weight (272 kg) on the manifest by more than 5 kg. Confirm the chute scale reading used for the dose calculation.'),
  ('71000003-0000-0000-0000-000000002502','70000002-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Re-verified at the chute — 278 kg is correct; the manifest carried an estimated arrival weight. Dose volume recalculated and unchanged.'),
  ('71000001-0000-0000-0000-000000000801','70000001-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Baseline owner PVAS of 7.2 is higher than the average of the pre-baseline diary entries (≈5.8). Please confirm the score was transcribed from the correct diary week.'),
  ('71000002-0000-0000-0000-000000000801','70000002-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Screening weight 31.2 kg differs from the referral record (29.4 kg). Confirm the scale reading and recent weight history.'),
  ('71000003-0000-0000-0000-000000000801','70000002-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Re-weighed on a calibrated scale at 31.2 kg; owner reports recent weight gain on the current diet. Value confirmed.'),
  ('71000004-0000-0000-0000-000000000801','70000003-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','CADESI-04 recorded as 22 but the uploaded lesion photographs suggest more extensive truncal involvement. Please re-score against the photo set and confirm.'),
  ('71000005-0000-0000-0000-000000000801','70000004-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Auto edit-check: Temperature 40.1 °C is above the expected range for dogs (38.3–39.2 °C) — verify the thermometer and re-check the patient for pyrexia.');
